package com.fitmind.controller; import com.fitmind.common.Result; import com.fitmind.dto.*; import com.fitmind.entity.UserProfile; import com.fitmind.service.ProfileService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import javax.validation.Valid;
@RestController @RequestMapping("/api/profile") @RequiredArgsConstructor public class ProfileController { private final ProfileService service; @GetMapping public Result<UserProfile> get(){return Result.ok(service.get());} @PutMapping public Result<UserProfile> update(@Valid @RequestBody ProfileUpdateRequest r){return Result.ok(service.update(r));} @PutMapping("/weight-unit") public Result<UserProfile> unit(@Valid @RequestBody WeightUnitRequest r){return Result.ok(service.updateUnit(r));} }
